const arenaKeys = (d: Record<string, string>) => Object.fromEntries(Object.entries(d).filter(([k]) => k.startsWith('arena_')));

/** Renvoie le jeu dans la langue de l'app. */
export const arenaHtml = (lang: Lang): string => {
  const payload = { lang, fr: arenaKeys(dictionary.fr), cur: arenaKeys(dictionary[lang]), tx: ARENA_TX[lang] };
  return ARENA_HTML.replace('<script>', '<script>window.__ARENA_I18N__=' + JSON.stringify(payload) + ';');
};
